#!/usr/bin/env python3
"""Apply explicit engineering reviews; never rewrite source pin types or UUIDs."""
import json,hashlib,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
lock=json.loads((ROOT/'parts.lock.json').read_text())
audit={}
def reviewed(k,pins,ratings,sources,notes,issues=()):
 p=lock['parts'][k];assert set(pins)=={v['number'] for v in p['pins']},k
 audit[k]={'pin_review':'DOCUMENT_REVIEWED','physical_pin_functions':pins,'ratings':ratings,'sources':sources,'notes':notes,'remaining_application_checks':list(issues),'source_archive_sha256':p['archive_sha256'],'raw_electrical_types_preserved':True}
for k,p in lock['parts'].items():
 if not k.startswith('r_'):continue
 v=p['library_properties']['Value'];m=p['mpn'];code=m[7:11]
 value=float(code[:3])*({'J':.1,'K':.01,'L':.001}.get(code[-1],10**int(code[-1]) if code[-1].isdigit() else 1))
 units={'Ω':1,'kΩ':1000,'MΩ':1000000}
 unit=next(u for u in ['kΩ','MΩ','Ω'] if v.endswith(u))
 assert math.isclose(float(v[:-len(unit)])*units[unit],value), (k,v,value)
 watts=1 if m[4:6]=='1W' else .25
 reviewed(k,{'1':'nonpolar resistive terminal','2':'nonpolar resistive terminal'}, {'resistance_ohm':value,'tolerance_fraction':.01,'power_W_at_70C':watts,'max_working_V':200,'allowable_continuous_V':min(200,math.sqrt(watts*value)),'power_derating':'100% at <=70C; linear to zero at155C'},['evidence/datasheets/uniroyal-resistors.pdf pp2,4-6',p['datasheet_url']], 'Exact manufacturer code decoded, compared with real library value '+v+'. Library IN / Undefined are retained; two-terminal passive behavior is separately documented. Voltage AND power limits apply.', ['Circuit voltage/power and local temperature require instance-level checks.'])
reviewed('pot_dual10k_log',{'1':'R1 CCW','2':'R1 wiper','3':'R1 CW','4':'R2 CCW (manufacturer circled1)','5':'R2 wiper (manufacturer circled2)','6':'R2 CW (manufacturer circled3)'},{'resistance_ohm':10000,'tolerance_fraction':.2,'taper':'15A logarithmic','power_W':.05,'max_DC_V':10,'gang_error_dB_max':3},['evidence/datasheets/ALPS-RK097.pdf pp1-2','https://tech.alpsalpine.com/e/products/detail/RK09712200HA/'],'Manufacturer mounting-side drawing No2 compared with two rows of library pads (1,2,3 and4,5,6); library numbering of second gang explicitly mapped. No fixed 50% electrical output is implied by mechanical mid-travel.',['Gang tracking at low volume needs measurement.'])
reviewed('jack_trs',{'1':'sleeve','2':'ring','3':'tip'},{'rated_V':30,'rated_A':.5},['evidence/datasheets/PJ-301C.pdf p1',lock['parts']['jack_trs']['datasheet_url']],'XKB terminal drawing: direct barrel sleeve1, intermediate ring2, far tip3; compare physical tab locations and native symbol.',['Output-capacitor short can exceed connector rating; protection fault test required.'])
reviewed('gain_dpdt',{'1':'poleA throw1','2':'poleA common','3':'poleA throw2','4':'poleB throw1','5':'poleB common','6':'poleB throw2','0':'library code for two mechanical shell tabs; not a signal contact'},{'rated_DC_V':30,'rated_A':.2,'poles':2,'positions':2},['evidence/datasheets/EG2208.pdf p1'],'Manufacturer circuit shows2/5 common and linked1-2,4-5 vs2-3,5-6. Extra pad0 is library mechanical-tab convention, absent as electrical terminal in manufacturer circuit. Preserve it and explicitly exclude from signal topology.',['Use intentional No Connect on shell0; do not silently delete.','Switch travel is specified as travel-to-make; bounce and simultaneous contact need transient test.'])
reviewed('hv_nmos',{'1':'gate','2':'drain','3':'source'},{'VDS_V':500,'VGS_abs_V':20,'Tj_max_C':150,'RthJC_C_per_W':.31,'RthCS_C_per_W':.25,'ID_A_at_Tc25':30},['evidence/datasheets/IXTH30N50L2.pdf pp1-6','https://www.littelfuse.com/assetdocs/littelfuse-discrete-mosfets-ixt-30n50-datasheet?assetguid=c09539a4-39f7-4fb5-940f-2103ab4fa891'],'IXYS DS99957B: TO247 pins1G2D3S and tab drain; source copy contains additional unrelated pages, only first6 pages authoritative for selected part. Extended DC FBSOA must be checked at actual case temperature.',['Heatsink/tab isolation, DC SOA and regulator stability need validation.'])
reviewed('hv_npn',{'1':'emitter','2':'base','3':'collector'},{'VCEO_V':300,'IC_A':.5,'PD_W_at25':.625,'Tj_max_C':150},['evidence/datasheets/MPSA42.pdf pp1-2'],'onsemi TO92 case29 1E2B3C agrees with symbol. Raw library marks all pins IN; this is not a correct BJT electrical classification and remains an explicit ERC limitation.',['Check thermal derating and second-breakdown SOA.'])
reviewed('heater_ldo',{'1':'adjust','2':'output','3':'input'},{'IO_A':5,'Vin_Vout_max_V':29,'dropout_max_V_at5A':1.5},['evidence/datasheets/LM1084.pdf'],'TI TO220 pinout1ADJ2OUT3IN; metal tab is OUT, so elevated heater heatsink requires insulation.',['ESR stability, minimum load, thermal and startup dropout validation.'])
reviewed('c_output_1000u250',{'1':'positive','2':'negative'},{'capacitance_F':.001,'rated_V':250,'tolerance_fraction':.2,'ripple_A_at120Hz85C':3.56,'leakage_A_max_at20C_5min':.0015},['evidence/datasheets/nichicon-LLS.pdf'],'LLS2E102MELB rating table and symbol plus marker at pin1. Leakage upper limit is 3sqrt(CuF*V) uA; NOT 3*C*V.',['Maximum permitted leakage gives24mV into16ohm/27mV into18ohm before other paths; <=2mV is NOT guaranteed.','Output-cap ESR, reverse voltage and ripple must be checked.'])
reviewed('c_hv_220u400',{'1':'positive','2':'negative'},{'capacitance_F':220e-6,'rated_V':400,'tolerance_fraction':.2,'ripple_A_at120Hz85C':1.64,'leakage_A_max_at20C_5min':3*math.sqrt(220*400)*1e-6},['evidence/datasheets/nichicon-LLS.pdf'],'2G is400V, confirmed part table; pin1 positive sign.',['Rectifier pulse ripple and discharge time need calculation.'])
reviewed('c_signal_4u7film',{'1':'nonpolar terminal','2':'nonpolar terminal'},{'capacitance_F':4.7e-6,'rated_V':450,'tolerance_fraction':.05},['https://industrial.panasonic.com/ww/products/pt/film-cap-electroequip/models/ECWFD2W475J'], 'Manufacturer exact part specification: metallized PP 4.7uF450V5%, lead pitch22.5mm.',['Confirm category-temperature voltage derating if hot enclosure.'])

for k,c,ripple,impedance in [('c_heater_3300u25',3300,3.82,.014),('c_cathode_2200u25',2200,3.63,.013),('c_control_470u25',470,1.29,.043),('c_delay_100u25',100,.455,.13)]:
 mpn=lock['parts'][k]['mpn']
 reviewed(k,{'1':'positive','2':'negative'},{'capacitance_F':c*1e-6,'rated_V':25,'tolerance_fraction':.2,'ripple_A_at100kHz105C':ripple,'impedance_ohm_at100kHz':impedance,'leakage_A_max_after2min':.01*c*25e-6},['https://industrial.panasonic.com/ww/products/pt/aluminum-cap-lead/models/'+mpn,'https://industrial.panasonic.com/cdbs/www-data/pdf/RDF0000/ABA0000C1259.pdf'], 'Exact Panasonic part checked against manufacturer ratings; positive symbol marker on pin1, negative sleeve identifies physical negative terminal. Manufacturer impedance at100kHz is NOT broadband ESR.', ['100Hz ripple rating needs frequency correction; do not use100kHz rating directly.','LLS and FR leakage use different formulas; keep separate.'])
 factor60,factor120=(.75,.80) if c>=1200 else ((.65,.75) if c>=390 else (.60,.70))
 audit[k]['ratings'].update(ripple_factor_60Hz=factor60,ripple_factor_120Hz=factor120,ripple_A_100Hz_conservative=ripple*factor60)
 audit[k]['notes']+=' FR-A datasheet01-Sep-2025 p1 frequency table visually verified. Use lower60Hz coefficient as conservative100Hz bound; waveform harmonics need RMS-weighted assessment.'
 audit[k]['remaining_application_checks'][0]='Rectifier pulse and harmonic RMS ripple require circuit measurement/simulation.'
 if c==100:audit[k]['notes']+=' Manufacturer product webpage labels0.13 as mOhm; PDF table and library agree0.13Ohm=130mOhm. This unit discrepancy is explicitly recorded, not silently copied.'
reviewed('d_heater_sb560',{'1':'cathode band','2':'anode'},{'VRRM_V':60,'IFavg_A':5,'IFSM_A_8p3ms':220,'Vf_max_V_at5A':.65,'Tj_max_C':150},['evidence/datasheets/SB560.pdf','https://www.vishay.com/docs/88721/sb520.pdf'],'Vishay DO201AD cathode band maps library1C; library2A. Manufacturer SPICE subcircuit uses1ANODE2CATHODE, so SPICE order MUST reverse library pin order.', ['Derate current by lead temperature and test rectifier charging pulse dissipation.'])
reviewed('d_small_1n4148',{'1':'cathode band','2':'anode'},{'VR_V':100,'IFavg_A':.2,'PD_W_at25':.5},['https://www.onsemi.com/download/data-sheet/pdf/1n914-d.pdf'], 'onsemi black cathode band; symbol cathode bar is on library pin1. Ammo packaging TA is documented.',['Pulse current and diode reverse voltage require instance checking.'])
reviewed('d_aux_1n4007',{'1':'cathode band','2':'anode'},{'VRRM_V':1000,'IFavg_A':1},['https://www.onsemi.com/download/data-sheet/pdf/1n4001-d.pdf',lock['parts']['d_aux_1n4007']['datasheet_url']], 'Rev18 June2024 pp1,2,5: cathode band; exact RLG ordering exists. Library1C2A.',['Check charging surge and junction temperature.'])
reviewed('d_hv_uf4007',{'1':'cathode band','2':'anode'},{'VRRM_V':1000,'IFavg_A':1,'IFSM_A_50Hz':30,'Vf_max_V_at1A':1.7},['https://diotec.com/en/product/UF4007.html'], 'DIOTEC exact part, DO41, cathode band maps library1C2A.',['Check high-voltage reservoir surge.'])
for k,v,lo,hi in [('z_ref_6v2',6.2,6.08,6.32),('z_aux_13v',13,12.7,13.3)]:
 reviewed(k,{'1':'cathode band','2':'anode'},{'Vz_nom_V':v,'Vz_at5mA_min_V':lo,'Vz_at5mA_max_V':hi,'PD_W_conservative':.4},['https://assets.nexperia.com/documents/data-sheet/BZX79.pdf','https://www.nexperia.com/product/BZX79-B6V2'], 'Nexperia B tolerance table, 5mA test current;400mW conservative ambient rating rather than500mW tie-point limit. Band is cathode.',['Zener noise, dynamic resistance and temperature drift require circuit review.'])
for k,v,iz in [('z_gate_12v',12,.021),('z_flyback_24v',24,.0105),('z_timer_5v1',5.1,.049)]:
 reviewed(k,{'1':'cathode band','2':'anode'},{'Vz_nom_V':v,'tolerance_fraction':.05,'test_current_A':iz,'PD_W_lead_cooled':1},['https://www.onsemi.com/download/data-sheet/pdf/1n4736at-d.pdf'], 'onsemi DO41 cathode band;1W is conditional on lead temperature/length, not an unconditional ambient allowance.',['Flyback pulse energy and lead-temperature derating need verification.'])
reviewed('fuse_heater_5a',{'1':'axial lead at first end cap','2':'axial lead at opposite end cap'},{'rated_A':5,'rated_AC_V':250,'breaking_A_at250VAC':1500,'cold_R_ohm_typ':.0153,'nominal_melting_I2t_A2s':66.095},['https://www.littelfuse.com/assetdocs/fuse-215-datasheet?assetguid=990f7193-d9a2-48e4-b760-2b43514249cf'], 'Exact0215005.MXEP/C142755 has factory axial leads; do not fit a holder or substitute cartridge MXP. Library terminal1/2 are nonpolar physical leads.',['Coordinate inrush/I2t, lead spacing and temperature.'])
reviewed('fuse_holder',{'1':'clip at first end','2':'clip at other end'},{'IEC_rated_V':250,'IEC_rated_A':6.3,'IEC_accepted_fuse_W':1.6,'pin_pitch_mm':22.6},['https://www.eaton.com/content/dam/eaton/products/electronic-components/resources/data-sheet/eaton-htc-fuse-holder.pdf'], 'Eaton HTC15M5x20, BK1 is1000-piece packaging. Two isolated clips; electrical connection exists only through inserted fuse.',['Use HTC140M insulating cover;5A fuse1.5In maxpower4W exceeds holder1.6W IEC envelope, so heater holder pairing is NOT qualified.'])
audit['fuse_holder']['remaining_application_checks']=['Only consider for primary/HV cartridge fuses after thermal coordination. Heater now uses factory axial-leaded fuse without holder. Fuse4W at1.5In and holder1.6W acceptance are different test conditions: this comparison identifies missing coordination evidence, not proof of thermal failure at normal current.']

if 'c_output_film_200u450' in lock['parts']:
 p=lock['parts']['c_output_film_200u450']
 audit['c_output_film_200u450']={'pin_review':'REJECTED_LIBRARY_GEOMETRY','sources':['evidence/datasheets/MKP1848.pdf pp3,4,7'],'expected_pin_count':6,'observed_symbol_pin_count':len(p['pins']),'observed_pad_count':len(p['pads']),'notes':'Exact200uF ordering row has footnote6, explicitly6 pins. Native library has only4 pins/pads. Do not silently adapt or approve; correction needs manufacturer cell connection map and new verified symbol/footprint.','raw_electrical_types_preserved':True,'source_archive_sha256':p['archive_sha256']}

# Only documentary results above receive reviewed status; missing audits are visible.
(ROOT/'parts.audit.json').write_text(json.dumps({'format':'quickpcb-parts-audit/v1','reviews':audit},ensure_ascii=False,indent=2)+'\n')
for k,p in lock['parts'].items():
 if k in audit:
  ok=audit[k]['pin_review']=='DOCUMENT_REVIEWED'
  p['review']={**p['review'],'pin_status':audit[k]['pin_review'],'rating_status':'DOCUMENT_REVIEWED' if ok else 'NOT_APPROVED','status':'APPLICATION_REVIEW_REQUIRED' if ok else 'REJECTED','audit_key':k}
lock['status']='PARTIAL_DOCUMENT_REVIEW';(ROOT/'parts.lock.json').write_text(json.dumps(lock,ensure_ascii=False,indent=2)+'\n')
print('Document-reviewed',sum(x['pin_review']=='DOCUMENT_REVIEWED' for x in audit.values()),'of',len(lock['parts']),'types; application qualification is still open.')
